 1	#!/usr/bin/env bash
 2	# Claude Code hook: copy the raw session transcript (prompts, responses, tool calls/results)
 3	# into ai-logs/claude-code/, masking secrets only. Runs on Stop / SubagentStop / PreCompact / SessionEnd.
 4	set -euo pipefail
 5	
 6	input=$(cat)
 7	transcript=$(jq -r '.transcript_path // empty' <<<"$input")
 8	session=$(jq -r '.session_id // empty' <<<"$input")
 9	[[ -n "$transcript" && -f "$transcript" && -n "$session" ]] || exit 0
10	
11	root="${CLAUDE_PROJECT_DIR:-$(pwd)}"
12	out="$root/ai-logs/claude-code"
13	mkdir -p "$out"
14	
15	mask() {
16	  perl -pe '
17	    s/sk-ant-[A-Za-z0-9_\-]{10,}/***/g;
18	    s/\bsk-[A-Za-z0-9_\-]{20,}/***/g;
19	    s/\b(gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})/***/g;
20	    s/\bAKIA[0-9A-Z]{16}\b/***/g;
21	    s/\bxox[abpr]-[A-Za-z0-9\-]{10,}/***/g;
22	    s/(Bearer\s+)[A-Za-z0-9._\-]{16,}/$1***/g;
23	    s/(Google Account: *** (\\"]+/$1*** /g;
24	    s/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/***/g;
25	    s/\Q$ENV{USER}\E/***/g if $ENV{USER};
26	    s/(?i)***(?![a-z])/***/g;
27	    s/***|***(?!드)/***/g;
28	  '
29	}
30	
31	mask <"$transcript" >"$out/$session.jsonl"
32	
33	# Subagent transcripts live next to the main one: <dir>/<session>/subagents/*.jsonl
34	sub="${transcript%.jsonl}/subagents"
35	if [[ -d "$sub" ]]; then
36	  mkdir -p "$out/$session-subagents"
37	  for f in "$sub"/*.jsonl; do
38	    [[ -f "$f" ]] && mask <"$f" >"$out/$session-subagents/$(basename "$f")"
39	  done
40	fi
41	exit 0
